datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

generator client {
  provider        = "prisma-client-js"
  previewFeatures = ["fullTextSearchPostgres"]
}

model Product {
  id          Int      @id @default(autoincrement())
  name        String
  description String
  category    String
  brand       String
  price       Float
  rating      Float
  inStock     Boolean
  createdAt   DateTime @default(now())
}

export async function devSeed(prisma: any) {
  // Clear existing products to ensure clean seed
  await prisma.product.deleteMany({});

  const products = [
    {
      name: "SuperFast Wireless Charger",
      description: "A high-speed wireless charging pad for all Qi-enabled smartphones and devices.",
      category: "Electronics",
      brand: "VoltCharge",
      price: 29.99,
